{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C23"],
      "claim": "Benazeprilat, the closest structural analogue (Morgan 0.7544), has absolute bioavailability of 27.1–28.5% when the active diacid is generated from oral benazepril, directly supporting F ≥20% for this benzazepinone diacid scaffold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C01"],
      "claim": "Benazepril, the prodrug of the closest analogue, has absolute oral bioavailability >37% in humans, supporting high F for the same core scaffold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C14"],
      "claim": "The lysine-containing ACE inhibitor SQ 29852 has 66% oral bioavailability in humans, demonstrating that the lysine side chain and diacid character are compatible with F ≥20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C25"],
      "claim": "Quinapril's active diacid principle has 46–52% oral bioavailability when given as the prodrug, another ACE inhibitor system above the threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C20"],
      "claim": "Temocaprilat reaches about 65% absolute bioavailability after oral temocapril, supporting high F for ACE inhibitor chemotypes.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C27"],
      "claim": "Olcegepant has <1% oral bioavailability, but it is a large peptide-like CGRP antagonist with very low similarity to the query; this is weak contradictory evidence.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "The query is a lysine-containing benzazepinone ACE inhibitor. The closest analogue benazeprilat and its prodrug show F 27–37%, and other ACE inhibitors, including a lysine-containing diacid, show F 46–66%. The only low-F evidence is from a structurally unrelated peptide-like molecule. Therefore F ≥20% is better supported.",
  "evidence_gaps": [
    "No direct absolute oral bioavailability measurement for the exact query molecule; closest data are for prodrug-derived active metabolites.",
    "The impact of the primary amine/lysine side chain on intestinal absorption and transporter-mediated uptake is inferred rather than directly measured."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

